import {comparison,HOUR} from './roi-change-model.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:2}):'—';
const time=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
async function read(path){const r=await fetch('/lan-api/roi-observations/'+path,{cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error?.message||'读取ROI对比失败');return j;}
function chart(m,r,key,mode){
 const percent=mode==='percent',values=m.pairs.flatMap(p=>percent?[p[key].percent]:[p.before?.[key],p.after?.[key]]).filter(Number.isFinite);let low=Math.min(0,...values),high=Math.max(0,...values);if(high===low)high=low+1;const pad=(high-low)*.1;high+=pad;if(percent)low-=pad;
 const y=v=>160-(v-low)/(high-low)*140,x=i=>60+860*(i+.5)/Math.max(m.count,1),tx=t=>60+860*(t-m.beforeStart)/Math.max(HOUR,m.afterEnd-m.beforeStart);
 let svg='<svg viewBox="0 0 960 205" role="img" aria-label="'+(key==='roi'?'实际综合营销ROI':'基础消耗')+(percent?'环比':'数值')+'小时曲线">';
 for(let i=0;i<4;i++){const v=low+(high-low)*i/3;svg+=`<line x1="60" x2="920" y1="${y(v)}" y2="${y(v)}" stroke="#e1e7f0"/><text x="53" y="${y(v)+4}" text-anchor="end">${num(v)}${percent?'%':''}</text>`;}
 if(percent)svg+=`<line x1="60" x2="920" y1="${y(0)}" y2="${y(0)}" stroke="#8994a8" stroke-dasharray="4 4"/>`;
 else if(m.count)svg+=`<line x1="${tx(Date.parse(r.changedAt))}" x2="${tx(Date.parse(r.changedAt))}" y1="15" y2="160" stroke="#d8982d" stroke-dasharray="5 4"/><text x="${tx(Date.parse(r.changedAt))+5}" y="25">修改ROI</text>`;
 for(const side of percent?['percent']:['before','after']){let line=[];const color=side==='before'?'#8795aa':key==='roi'?'#4164e8':'#009c99';const flush=()=>{if(line.length)svg+=`<polyline points="${line.join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`;line=[];};
  m.pairs.forEach((p,i)=>{const v=percent?p[key].percent:p[side]?.[key];if(!Number.isFinite(v)){flush();return;}const xx=percent?x(i):tx(p[side+'Time']+HOUR/2);line.push(xx+','+y(v));svg+=`<circle cx="${xx}" cy="${y(v)}" r="4" fill="${color}"><title>${esc('前 '+time(p.beforeTime)+'：'+num(p.before?.[key])+'；后 '+time(p.afterTime)+'：'+num(p.after?.[key])+'；'+p[key].text)}</title></circle>`;});flush();}
 if(!values.length)svg+='<text x="480" y="90" text-anchor="middle">暂无可比小时数据</text>';
 if(percent)m.pairs.forEach((p,i)=>{if(m.count<=12||i%2===0)svg+=`<text x="${x(i)}" y="188" text-anchor="middle">第${i+1}小时</text>`;});
 else if(m.count)for(const t of [m.beforeStart,m.beforeEnd,m.afterStart,m.afterEnd])svg+=`<text x="${tx(t)}" y="188" text-anchor="middle">${time(t)}</text>`;
 return svg+'</svg>';
}
export async function openRoiChanges(planId){
 if(!document.querySelector('link[data-roi-style]')){const link=document.createElement('link');link.rel='stylesheet';link.href='/roi-change.css';link.dataset.roiStyle='1';document.head.append(link);}
 const d=document.createElement('dialog');d.className='roi-dialog';d.setAttribute('aria-label','ROI调整前后对比');d.innerHTML='<header><div><h2>ROI调整前后对比</h2><small>实际综合营销ROI · 基础消耗 · 仅记录本网站成功修改</small></div><button data-close aria-label="关闭ROI对比">×</button></header><section class="roi-content">正在读取…</section><footer><button data-close>关闭</button></footer>';document.body.append(d);d.showModal();
 const content=d.querySelector('.roi-content');let record=null,range={from:0,to:'all'},mode='percent',timer,generation=0;
 function render(){
  const m=comparison(record,range,Date.parse(record.asOf));
  content.innerHTML=`<div class="roi-context"><b>${esc(record.name)}</b><span>目标ROI ${num(record.before)} → ${num(record.after)}</span><span>修改：${time(record.changedAt)}</span><span>${record.status==='tracking'?'跟踪中，最长24小时':record.status==='interrupted'?'被后续调整打断':'已停止跟踪，历史结果'}</span></div><div class="roi-controls">${[['all','全部已观察'],[3,'前3小时'],[6,'前6小时'],[12,'前12小时'],[24,'前24小时']].map(([v,label])=>`<button data-range="${v}" class="${range.from===0&&String(range.to)===String(v)?'active':''}">${label}</button>`).join('')}<label>自定义：修改后第 <input data-from aria-label="起始观察小时" type="number" min="0" max="23" value="${range.from}"> 至 <input data-to aria-label="结束观察小时" type="number" min="1" max="24" value="${range.to==='all'?24:range.to}"> 小时</label><button data-apply>应用为对比区间</button><select data-mode aria-label="曲线展示方式"><option value="percent" ${mode==='percent'?'selected':''}>环比变化（%）</option><option value="raw" ${mode==='raw'?'selected':''}>原始数值</option></select></div><p class="roi-note">已观察 ${num(m.observedHours)} 小时；前后各 ${m.count} 个完整小时参与比较。混合小时和未满小时不参与环比。${record.loading?'正在更新数据…':''}${record.updatedAt?' 数据更新：'+time(record.updatedAt):''}</p>${record.error?'<p class="roi-error">'+esc(record.error)+'；保留上次成功数据。</p>':''}<p>前：${time(m.beforeStart)}—${time(m.beforeEnd)}　后：${time(m.afterStart)}—${time(Math.max(m.afterStart,m.afterEnd))}</p><div class="roi-cards">${[['roi','实际综合营销ROI',''],['spend','基础消耗',' 元']].map(([k,label,unit])=>`<article><h3>${label}</h3><strong>${num(m[k].before)}${unit} → ${num(m[k].after)}${unit}</strong><p>${esc(m[k].text)}</p></article>`).join('')}</div>${[['roi','实际综合营销ROI'],['spend','基础消耗（元）']].map(([k,label])=>`<section class="roi-chart"><h3>${label}${mode==='percent'?' · 每小时环比':''}</h3>${chart(m,record,k,mode)}</section>`).join('')}<p class="roi-note">每小时环比对齐所选前后区间的对应小时；切换区间时，对照小时会变化。缺失或前值为0时保留断点。原始图灰线为修改前，彩线为修改后。</p><details><summary>查看小时明细及对应时间</summary><div class="roi-table"><table><thead><tr><th>修改前小时</th><th>修改后小时</th><th>实际ROI 前→后</th><th>ROI环比</th><th>基础消耗 前→后</th><th>消耗环比</th></tr></thead><tbody>${m.pairs.map(p=>`<tr><td>${time(p.beforeTime)}</td><td>${time(p.afterTime)}</td><td>${num(p.before?.roi)} → ${num(p.after?.roi)}</td><td>${esc(p.roi.text)}</td><td>${num(p.before?.spend)} → ${num(p.after?.spend)}</td><td>${esc(p.spend.text)}</td></tr>`).join('')}</tbody></table></div></details><p><button data-history>返回调整记录</button></p>`;
 }
 async function load(id){const rev=++generation;clearTimeout(timer);try{const value=await read('record?id='+encodeURIComponent(id));if(!d.open||rev!==generation)return;record=value;render();if(record.loading||record.status==='tracking')timer=setTimeout(()=>void load(id),record.loading?5000:60000);}catch(e){if(d.open)content.textContent=e.message;}}
 async function history(){generation++;clearTimeout(timer);record=null;const data=await read('list'+(planId?'?planId='+encodeURIComponent(planId):''));if(!d.open)return;content.innerHTML=data.records.length?`<div class="roi-records">${data.records.map(r=>`<button data-record="${esc(r.id)}"><b>${esc(r.name)}</b><span>${time(r.changedAt)} · 目标ROI ${num(r.before)} → ${num(r.after)}</span><small>${r.active?'跟踪中':'历史记录'}</small></button>`).join('')}</div>`:'<p>暂无本网站成功修改ROI的记录。启用后的成功修改会自动建立对比，已有计划不会被自动当成修改记录。</p>';}
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))return d.close();if(b.dataset.record){range={from:0,to:'all'};void load(b.dataset.record);}if(b.hasAttribute('data-range')){range={from:0,to:b.dataset.range==='all'?'all':Number(b.dataset.range)};render();}if(b.hasAttribute('data-apply')){try{const q={from:Number(d.querySelector('[data-from]').value),to:Number(d.querySelector('[data-to]').value)};comparison(record,q,Date.parse(record.asOf));range=q;render();}catch(e){const p=document.createElement('p');p.className='roi-error';p.textContent=e.message;content.prepend(p);}}if(b.hasAttribute('data-history'))void history().catch(e=>content.textContent=e.message);});
 d.addEventListener('change',e=>{if(e.target.hasAttribute('data-mode')){mode=e.target.value;render();}});d.addEventListener('close',()=>{generation++;clearTimeout(timer);d.remove();});await history().catch(e=>content.textContent=e.message);
}
